class Solution {
public:
    int maxDistance(string moves) {
        int L = 0, R = 0, U = 0, D = 0, c = 0;
        for (char ch : moves) {
            if (ch == 'L') L++;
            else if (ch == 'R') R++;
            else if (ch == 'U') U++;
            else if (ch == 'D') D++;
            else c++;
        }
        return max(abs(R - L) + c, abs(U - D) + c);
    }
};

