class Solution {
    public int maxDistance(String moves) {
        int l = 0, r = 0, u = 0, d = 0, c = 0;
        for (char ch : moves.toCharArray()) {
            switch (ch) {
                case 'L': l++; break;
                case 'R': r++; break;
                case 'U': u++; break;
                case 'D': d++; break;
                default: c++;
            }
        }
        return Math.max(Math.abs(r - l) + c, Math.abs(u - d) + c);
    }
}

