class Solution:
    def maxDistance(self, moves: str) -> int:
        xlo = xhi = ylo = yhi = 0
        for ch in moves:
            if ch == '_':
                xlo -= 1; xhi += 1; ylo -= 1; yhi += 1
            elif ch == 'L':
                xlo -= 1; xhi -= 1
            elif ch == 'R':
                xlo += 1; xhi += 1
            elif ch == 'U':
                ylo += 1; yhi += 1
            else:
                ylo -= 1; yhi -= 1
        return max(abs(xlo), abs(xhi)) + max(abs(ylo), abs(yhi))

