        for (char ch : moves) {
            if (ch == '_') { xlo--; xhi++; ylo--; yhi++; }
            else if (ch == 'L') { xlo--; xhi--; }
            else if (ch == 'R') { xlo++; xhi++; }
            else if (ch == 'U') { ylo++; yhi++; }
            else { ylo--; yhi--; }
        }
        return max(abs(xlo), abs(xhi)) + max(abs(ylo), abs(yhi));
    }
};

